-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla enemies con la categoria fauna y la columna drops).
--
-- Enemigos de Genshin Impact: los 569 del archivo del juego, divididos en
-- jefes (61), esbirros (285, de los que 80 son elites) y fauna (223).
--
-- Fuentes:
--   Yatta (gi.yatta.moe) -> nombre y descripcion oficiales en espanol e ingles,
--     faccion, resistencias, botin, consejos de combate e imagen.
--   Datos del propio juego (AnimeGameData, de Dimbreath) -> rango.
--
-- En Genshin no hay debilidades como en Honkai: cada enemigo tiene una
-- resistencia a cada elemento (normalmente 10%). En weaknesses van los
-- elementos con resistencia negativa, y en resistances las ocho, con las
-- inmunidades marcadas. Las versiones con resistencias distintas (Abismo,
-- eventos...) quedan en variants.
--
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada.
--
-- Generado el 2026-09-15.

--
-- PARTE 1 de 4 (80 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 4 partes, en cualquier orden.

insert into public.enemies (
  id, game_id, name, name_en, category, rank, faction, description, image_url, weaknesses, resistances, variants, skills, drops
)
values
  ('gi-enemy-29122000', 'genshin-impact', 'Ajedrez Guardapuertas', 'The Game Before the Gate', 'jefe', 'jefe', 'Enemigos memorables', 'La octava de Los Once de los Fatui

Una especie de ejército creado gracias a las habilidades de varias brujas del Aquelarre.
Aunque funciona con tecnología actual que no está relacionada con la profunda sabiduría de los fundamentos del universo, los mecanismos que lo componen vigilan el último umbral de la puerta y son una metáfora en sí mismos.
Puede que en este mundo haya reglas, pero estas dejan de aplicarse una vez que cruzas la puerta.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_GiantChess.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":70},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":70},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-24050101', 'genshin-impact', 'Algoritmo de Semi-Incesante Matriz de Observación Navegadora', 'Algorithm of Semi-Intransient Matrix of Overseer Network', 'jefe', 'jefe', 'Autómatas', 'Una máquina de moción perpetua que ejerce control sobre las numerosas ruinas que hay en el desierto. Parece que la voluntad de cierto rey solitario aún reside en ella.
Tal vez fuera porque recibió instrucción de un amigo en un sueño o porque ansiaba la autoridad que poseían los dioses, pero el rey de esta perdida nación creó misteriosas máquinas que no debían haber tenido cabida en este mundo.
En mitad de las abandonadas ruinas de la ciudad de los mil pilares, los antiguos cristales yacen en la arena, vestigio de la gloria del paraíso dorado, aunque ya nadie quede para rememorar los sueños de su rey.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Monolith_Starchild.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una antigua maquinaria del desierto con unas características que escapan al conocimiento de la civilización actual. Durante el combate, el Algoritmo de Semi-Incesante Matriz de Observación Navegadora lanza los componentes de su propia estructura, su núcleo se vuelve invisible y aumenta considerablemente su resistencia al daño. Consigue afectar al núcleo con una reacción de Catalización o utiliza ataques Electro mientras se recupera después de haber destruido sus componentes para romper la invisibilidad del Algoritmo de Semi-Incesante Matriz de Observación Navegadora y hacer que entre en un estado de supersobrecarga. Si tardas demasiado en romper la invisibilidad de su núcleo, liberará una onda de alta frecuencia muy poderosa.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Pedacito de ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104111.png","rareza":2},{"nombre":"Fragmento de ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104112.png","rareza":3},{"nombre":"Trozo de ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104113.png","rareza":4},{"nombre":"Ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104114.png","rareza":5},{"nombre":"Pedacito de turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104151.png","rareza":2},{"nombre":"Fragmento de turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104152.png","rareza":3},{"nombre":"Trozo de turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104153.png","rareza":4},{"nombre":"Turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104154.png","rareza":5},{"nombre":"Tetraedro guialuz","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113039.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Aventurero","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10010_4.png","rareza":3},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":4},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":5},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":4},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":5},{"nombre":"Ritual de la Iluminación","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15009_3.png","rareza":3},{"nombre":"Ritual de la Iluminación","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15009_3.png","rareza":4}]'::jsonb),
  ('gi-enemy-25520101', 'genshin-impact', 'Asceta Espiritista', 'Wayward Hermetic Spiritspeaker', 'jefe', 'jefe', 'Humanos', 'Una sacerdotisa de los Augures Vientonocturno que vive recluida lejos de la tribu. Se dice que, como recibió la protección de la Wayob de los Augures Vientonocturno, posee un poder de espiritismo superior al de la mayoría de sacerdotes y chamanes. Un poder así es tanto una bendición como una maldición, pues a los sacerdotes incapaces de controlarlo no les queda otra opción que alejarse de la tribu hasta que aprendan a dominarlo. Aunque hoy en día ya controla esta fuerza con maestría, se ha acostumbrado a la vida lejos de la tribu, lo que ha dado pie a rumores sobre lo poco que le gusta tratar con las demás personas. Dicen que está dispuesta siempre a ayudar a los más jóvenes que acuden a ella en busca de iluminación, pero, claro está, a su manera...', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_TribalWarrior_Udugan.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":70},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"El Asceta Espiritista invocará reflejos radiantes idénticos y se ocultará entre ellos. Destruye todas las protecciones elementales de los reflejos radiantes durante este tiempo para revelar y debilitar el cuerpo real. Además, los Iktomisaurios y los Augures Vientonocturno pueden mantener pulsado para apuntar a los reflejos radiantes y, así, detener su movimiento durante un breve periodo de tiempo...","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Pedacito de jade shivada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104161.png","rareza":2},{"nombre":"Fragmento de jade shivada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104162.png","rareza":3},{"nombre":"Trozo de jade shivada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104163.png","rareza":4},{"nombre":"Jade shivada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104164.png","rareza":5},{"nombre":"Talismán de la tierra enigmática","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113071.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Afortunado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10011_4.png","rareza":3},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":4},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":5},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":4},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":5},{"nombre":"Ritual de la Primavera","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15013_3.png","rareza":3},{"nombre":"Ritual de la Primavera","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15013_3.png","rareza":4}]'::jsonb),
  ('gi-enemy-24090201', 'genshin-impact', 'Autómata Fuentenigma - Máquina configuracional', 'Secret Source Automaton: Configuration Device', 'jefe', 'jefe', 'Autómatas', 'Una máquina constructora hallada en ruinas antiguas. Este tipo de máquina, capaz de adoptar numerosas formas, era utilizada por los maestros de las antiguas ruinas para realizar diversas tareas de fabricación. Si aprendes a utilizarla, podrás construir una ciudad colosal más allá de la imaginación, incluso en entornos extremos como las profundidades de un volcán.
Además, al parecer puede utilizarse como arma. Aunque la antigua civilización ha caído hace tiempo, esta máquina, con forma de garra gigante e impulsada por los diseños dorados grabados en ella, aún puede entrar en combate siguiendo sus instrucciones preestablecidas.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_DragonClaw.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una máquina con poderosas funciones destructivas. Cuando los personajes entran y mantienen el estado de bendición noctámbula, el Autómata Fuentenigma - Máquina configuracional comenzará a acumular progreso de “contramedidas combativas”. Una vez alcanzado el máximo de acumulaciones, liberará un electrocañonazo y, al hacerlo, activará sus dispositivos condensadores para excavar el flogisto sólido y extraer flogisto de él. Los dispositivos condensadores también crearán un campo de fuerza que podrás destruir si interrumpes la carga del electrocañonazo, para lo cual tendrás que escalar el flogisto sólido y entrar en dicho campo de fuerza.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Pedacito de amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104141.png","rareza":2},{"nombre":"Fragmento de amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104142.png","rareza":3},{"nombre":"Trozo de amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104143.png","rareza":4},{"nombre":"Amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104144.png","rareza":5},{"nombre":"Núcleo fuentenigmático con grabados de oro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113066.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":4},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":5},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":4},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":5},{"nombre":"Ritual de la Sabiduría","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15011_3.png","rareza":3},{"nombre":"Ritual de la Sabiduría","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15011_3.png","rareza":4}]'::jsonb),
  ('gi-enemy-24090501', 'genshin-impact', 'Autómata Fuentenigma - Máquina de control', 'Secret Source Automaton: Overseer Device', 'jefe', 'jefe', 'Autómatas', 'Un mecanismo de control de ruinas antiguas.
En la antigüedad, una grandiosa raza concedió una parte de su autoridad a la sabiduría creada a partir de flogisto para mantener en funcionamiento una enorme ciudad. Impulsadas por su misión y por toda clase de mecanismos, las máquinas a las que se concedió aquella sabiduría controlaban el funcionamiento de un sinfín de ciudades en la tierra. Sin embargo, la antigua civilización cayó en la guerra contra la nueva especie, de manera que en los mecanismos de control que albergaban una gran sabiduría ya no quedan más que las órdenes más sencillas.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_DragonCollar.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un mecanismo de control creado por una antigua civilización próspera para controlar el funcionamiento de las Máquinas Fuentenigma. Al entrar en “modo purga”, empezará a generar ímpetu torrencial mientras ataca. Cuanto más ímpetu torrencial tenga, más daño infligirá. Si lo atacas continuamente con el elemento Cryo, tal vez puedas detener la acumulación de ímpetu torrencial.\nSe dice que, cuando un personaje entra en el estado de bendición noctámbula y permanece en él durante cierto tiempo, el Autómata Fuentenigma - Máquina de control entra en un “estado de combate” especial con el que cambia su modo de ataque.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Pedacito de lazurita varunada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104121.png","rareza":2},{"nombre":"Fragmento de lazurita varunada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104122.png","rareza":3},{"nombre":"Trozo de lazurita varunada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104123.png","rareza":4},{"nombre":"Lazurita varunada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104124.png","rareza":5},{"nombre":"Acumulador de aire fuentenigma","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113076.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Aventurero","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10010_4.png","rareza":3},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":4},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":5},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":4},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":5},{"nombre":"Ritual del Destino","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15010_3.png","rareza":3},{"nombre":"Ritual del Destino","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15010_3.png","rareza":4}]'::jsonb),
  ('gi-enemy-29040101', 'genshin-impact', 'Azhdaha', 'Azhdaha', 'jefe', 'jefe', 'Enemigos memorables', 'Rey Dragón de la Roca sellado

Un enorme dragón tan antiguo como las montañas.
En una época que ya nadie recuerda, fue el compañero del gobernante del Puerto de Piedra. Pero, al final, entre ellos surgió un conflicto y el dragón fue encerrado en las profundidades de la tierra. Durante los largos años de confinamiento, su poder se disipó lentamente y su apariencia quedó desfigurada.
El tintineo de los grilletes que aprisionan al dragón y sus profundos gruñidos resuenan en el interior de la montaña como los recuerdos de un tiempo pasado.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Dahaka.png', '[]'::jsonb, '[{"elemento":"Físico","valor":40},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":70}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Prototipo de espada del Norte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101101.png","rareza":4},{"nombre":"Prototipo de arco del Norte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101102.png","rareza":4},{"nombre":"Prototipo de mandoble del Norte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101103.png","rareza":4},{"nombre":"Prototipo de catalizador del Norte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101104.png","rareza":4},{"nombre":"Prototipo de lanza del Norte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101105.png","rareza":4},{"nombre":"Pedacito de ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104111.png","rareza":2},{"nombre":"Fragmento de ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104112.png","rareza":3},{"nombre":"Trozo de ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104113.png","rareza":4},{"nombre":"Ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104114.png","rareza":5},{"nombre":"Pedacito de amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104141.png","rareza":2},{"nombre":"Fragmento de ama