ps://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":5},{"nombre":"Ritual de la Primavera","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15013_3.png","rareza":3},{"nombre":"Ritual de la Primavera","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15013_3.png","rareza":4},{"nombre":"Fragmento de hueso frágil","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112041.png","rareza":2},{"nombre":"Fragmento de hueso sólido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112042.png","rareza":3},{"nombre":"Fragmento de hueso fosilizado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112043.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3}]'::jsonb),
  ('gi-enemy-24030301', 'genshin-impact', 'Dragón Aciagoeterno', 'Aeonblight Drake', 'jefe', 'jefe', 'Autómatas', 'Una máquina de guerra con aspecto de dragón tan aterradora como el soberano que en la antigüedad gobernó estas vastas tierras.
Cuentan las leyendas que aquella nación, ahora en ruinas, intentó alcanzar un conocimiento prohibido para crear máquinas de moción perpetua capaces de igualar, e incluso superar, a las formas de vida primigenias. La existencia de este misterioso monstruo mecánico e incansable es prueba de que la legendaria nación que desapareció alcanzó hitos que los mortales nunca deberían haber alcanzado.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Gargoyle_Fafnir.png', '[]'::jsonb, '[{"elemento":"Físico","valor":70},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una máquina de las ruinas capaz de absorber energía y contraatacar. Es más poderosa que los Dragones de las Ruinas y es capaz de atacar tanto estando sobre el suelo como en el aire. Durante el combate, el Dragón Aciagoeterno liberará cada cierto tiempo una peligrosa corriente de energía y, en función del tipo de daño elemental que haya recibido antes, aumentará su RES a ese elemento en concreto. En ciertas condiciones, los núcleos de varias partes de su cuerpo quedarán expuestos. Aprovecha esta oportunidad para atacar sus núcleos y, así, paralizarlo y anular su aumento de RES Elemental. Tras recuperarse de la parálisis, volverá a estar sobre el suelo o en el aire.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Pedacito de lazurita varunada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104121.png","rareza":2},{"nombre":"Fragmento de lazurita varunada","icono":"https://gi.