_15001_4.png","rareza":5},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":4},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":5}]'::jsonb),
  ('gi-enemy-26190101', 'genshin-impact', 'Suanni Ermitaña', 'Solitary Suanni', 'jefe', 'jefe', 'Bestias exóticas', 'Una elegante y fría bestia divina que solamente habita en montañas donde aún queda poder adéptico.
Desde la antigüedad, esta bestia iluminada se considera un símbolo de buena fortuna, y ha sido aclamada por los intelectuales generación tras generación por vivir recluida en las montañas, alejada de las perturbaciones mundanas. Según una antigua leyenda del Valle Chenyu, la líder de los suanni se hacía llamar “Maestra de la Montaña”, y se la solía considerar a la par que los Adeptus.
También hay quien dice que las Bestias Xuanwen que deambulan por las montañas en el presente son las descendientes de estas bestias iluminadas, pero que debido a su lejano parentesco con los Adeptus, no pudieron heredar su sangre noble y acabaron convirtiéndose en bestias violentas. Esta hipótesis se contradice con otra que trata sobre el origen de las Bestias Xuanwen, pero aun así, en las pocas fuentes que hablan sobre los suanni, se menciona que solían ir acompañadas de dichas bestias.
La danza de bestias que todo el mundo conoce hoy en día en el Valle Chenyu es un espectáculo que consiste en imitar los movimientos y el porte de los legendarios suanni. No obstante, muy poca gente ha visto alguna vez un suanni de verdad, por lo que a la mayoría no le queda más remedio que imaginar cómo son a través de descripciones. Así fue como, tras miles de años de cambios y evolución artística, las máscaras de bestias adoptaron el aspecto que tienen en la actualidad.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hermit.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":70},{"elemento":"Anemo","valor":70},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una bestia iluminada que vive en las profundidades de la montaña y que combate manipulando los elementos Hydro y Anemo. Congélala cuando empiece a usar su poder adéptico Hydro y usa las Reacciones Elementales de Rompehielo o Derretido para destruir el hielo y paralizar temporalmente a la bestia. Cuando empiece a usar el poder adéptico Anemo, atácala con elementos que reaccionen con dicho elemento para destruir las aeroesferas que invoca y, así, hacerte con la ventaja del combate.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Pedacito de lazurita varunada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104121.png","rareza":2},{"nombre":"Fragmento de lazurita varunada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104122.png","rareza":3},{"nombre":"Trozo de lazurita varunada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104123.png","rareza":4},{"nombre":"Lazurita varunada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104124.png","rareza":5},{"nombre":"Pedacito de turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104151.png","rareza":2},{"nombre":"Fragmento de turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104152.png","rareza":3},{"nombre":"Trozo de turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104153.png","rareza":4},{"nombre":"Turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104154.png","rareza":5},{"nombre":"Nimboescama","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113058.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Afortunado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10011_4.png","rareza":3},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":4},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":5},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":4},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":5}]'::jsonb),
  ('gi-enemy-24070301', 'genshin-impact', 'Suite Criocéfiro', 'Icewind Suite', 'jefe', 'jefe', 'Autómatas', 'Condena de Coppélius

Una deslumbrante pareja de bailarines mecánicos creados por el Instituto de Ciencias de Fontaine.
En sus primeros bocetos, Bossuet pensó que los bailarines eran una obra de arte capaz de superar cualquier otro invento basado en la replicación mecánica. Sin embargo, cuando le obligaron a abandonar el Instituto, Maillardet asumió el control de la investigación. Este poseía una visión única de lo que debían ser los mecanismos y los bailarines, por lo que, durante el proceso de iteración, al tiempo que perfeccionaba las distintas funciones de los bailarines, se fue desviando de la idea original de la que partió Bossuet.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_MachinaIustitia_Nutcracker.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":70},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":70},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Una fantástica actuación traída por Maillardet, del Instituto de Ciencias de Fontaine, y representada por los Mecabots Coppélia y Coppélius. Antes de comenzar el desafío, deberás hablar con Maillardet para escoger la pieza musical que desees. Las recompensas que obtengas de la Flor ley que aparezca tras superar el desafío dependerán de la pieza musical que escogiste.","tipo":"consejo","elemento":null},{"nombre":"Consejo de combate","descripcion":"«Funeral de Coppélia»: la protagonista es la dama Mecabot Coppélia. En el punto álgido de su actuación, Coppélia se detendrá en el centro de la pista de baile para dar el máximo de sí misma e invocar los infinitos vientos mortuorios en un alarde de su característica energía ousía mecánica.","tipo":"consejo","elemento":null},{"nombre":"Consejo de combate","descripcion":"«Condena de Coppélius»: el protagonista de esta pieza es el aristócrata Coppélius. En el punto álgido de su actuación, Coppélius se detendrá en el centro de la pista de baile para dar el máximo de sí mismo, defenderse con una protección y crear tres corazones de escarcha de la condena, todo ello en un alarde de su característica energía pneuma mecánica.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Pedacito de turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104151.png","rareza":2},{"nombre":"Fragmento de turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104152.png","rareza":3},{"nombre":"Trozo de turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104153.png","rareza":4},{"nombre":"Turquesa vayuda","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104154.png","rareza":5},{"nombre":"Pedacito de jade shivada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104161.png","rareza":2},{"nombre":"Fragmento de jade shivada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104162.png","rareza":3},{"nombre":"Trozo de jade shivada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104163.png","rareza":4},{"nombre":"Jade shivada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104164.png","rareza":5},{"nombre":"Recambio mecánico de Coppélia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113049.png","rareza":4},{"nombre":"Recambio mecánico de Coppélius","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113050.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Afortunado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10011_4.png","rareza":3},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":4},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":5},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":4},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":5},{"nombre":"Ritual de la Primavera","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15013_3.png","rareza":3},{"nombre":"Ritual de la Primavera","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15013_3.png","rareza":4}]'::jsonb),
  ('gi-enemy-22150101', 'genshin-impact', 'Susurrador de Pesadillas de las Profundidades Insondables', 'Lord of the Hidden Depths: Whisperer of Nightmares', 'jefe', 'jefe', 'Abismo', 'Dominador sin rostro ni dominio

Una criatura del Abismo que acecha a través de fisuras en las profundidades insondables, observando el mundo en silencio. Se dice que su siniestra forma sin rostro no es más que una proyección, pues su verdadero cuerpo solo existe como una masa amorfa de energía pura del Abismo.
Incluso los invasores que buscan reclamar este mundo deben obedecer sus normas en cierta manera. Mientras no se parta el firmamento ni colapsen las defensas de la tierra, estas criaturas venidas de las estrellas no podrán hacer más que permanecer en los límites del mundo, susurrando delirios y sin conseguir penetrar más allá... Pero ¿cuánto tiempo más lograrán aguantar la estabilidad y el orden?', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Lloigor_Primo.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"El monarca de la manada de monstruos que emergió de una fisura de las profundidades insondables. El Susurrador de Pesadillas de las Profundidades Insondables hará que el escudo insondable se expanda durante el combate, con lo que invocará varios Pescadores de las Profundidades Insondables. El escudo solo podrá romperse con ataques elementales o daño de reacciones. El daño de Reacciones Lunares será especialmente efectivo para destruir dicho escudo. Además, al derrotar a un Pescador de las Profundidades Insondables invocado, el escudo también sufrirá daño.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Pedacito de amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104141.png","rareza":2},{"nombre":"Fragmento de amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104142.png","rareza":3},{"nombre":"Trozo de amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104143.png","rareza":4},{"nombre":"Amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104144.png","rareza":5},{"nombre":"Vestigio de las alas del terror","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113084.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":3},{"nombre":"Exiliado","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10009_4.png","rareza":4},{"nombre":"Médica Itinerante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10013_4.png","rareza":3},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":4},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":5},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":4},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":5},{"nombre":"Ritual de la Sabiduría","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15011_3.png","rareza":3},{"nombre":"Ritual de la Sabiduría","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15011_3.png","rareza":4}]'::jsonb),
  ('gi-enemy-26230301', 'genshin-impact', 'Tirano Qucusaurio Aureoardiente', 'Goldflame Qucusaur Tyrant', 'jefe', 'jefe', 'Bestias exóticas', 'Un Qucusaurio que ha obtenido un cuerpo sobrenatural debido a un enorme poder imposible de controlar por los saurios de la actualidad.
Según una antigua leyenda, cuando era pequeño, el gran saurio alado que ahora suele deambular entre la bruma de la montaña fue de aventuras con los héroes que salvaron Natlan. Cuentan que uno de esos héroes prometió hacer el peregrinaje al volcán con este saurio para evitar que perdiera la cordura a causa del agresivo poder que fluía por su sangre. A juzgar por el nombre de “tirano” con el que la gente se refiere a él hoy en día, aquella historia no debió de terminar muy bien...', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Natsaurus_Flamingo_Primo.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":70},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un Qucusaurio cuya extraordinaria forma es el resultado de su incapacidad de soportar el gran poder que posee. Vuela hacia el cielo durante el combate y entra en el estado “aureoardiente” cargado de energía, creando una protección a su alrededor y bombardeando la superficie con un “penacho ventofulgente”. Si no logras destruirlo antes de que el Qucusaurio se sumerja en él, la criatura utilizará una corriente de flogisto para volver al cielo hasta que se agote y vuelva a su forma original. Parece, pues, que destruir el penacho ventofulgente apoyándote de elementos que reaccionen con Pyro podría ser la clave de la victoria...","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Pedacito de ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104111.png","rareza":2},{"nombre":"Fragmento de ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104112.png","rareza":3},{"nombre":"Trozo de ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104113.png","rareza":4},{"nombre":"Ágata agnidus","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104114.png","rareza":5},{"nombre":"Sello de la bendición vinculante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113064.png","rareza":4},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":3},{"nombre":"Berserker","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10005_4.png","rareza":4},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":3},{"nombre":"Instructor","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10007_4.png","rareza":4},{"nombre":"Aventurero","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_10010_4.png","rareza":3},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":4},{"nombre":"Final del Gladiador","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15001_4.png","rareza":5},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":4},{"nombre":"Orquesta del Errante","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15003_4.png","rareza":5},{"nombre":"Ritual de la Iluminación","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15009_3.png","rareza":3},{"nombre":"Ritual de la Iluminación","icono":"https://gi.yatta.moe/assets/UI/reliquary/UI_RelicIcon_15009_3.png","rareza":4}]'::jsonb),
  ('gi-enemy-29060201', 'genshin-impact', 'Todopoderosa Narukami de la catástrofe', 'Magatsu Mitake Narukami no Mikoto', 'jefe', 'jefe', 'Enemigos memorables', 'La poderosa marioneta que actúa en nombre de la Shogun Raiden para hacer frente a los enemigos que suponen una amenaza contra la eternidad.
Como asistente de Raiden Ei y ejecutora de la eternidad, nunca cuestiona las cosas, no siente miedo y, sin pensamientos que la distraigan, siempre se ha esforzado al máximo para dicha causa.
Alguna vez escuchó que, durante el gobierno de Makoto y Ei, esta última tenía una responsabilidad parecida a ella, y que más tarde experimentó una dolorosa pérdida.
Cuando ambas sombras se unieron, ella solo podía ver las pequeñas, pero incontables, fracturas que había en su voluntad, la cual debería haber sido eterna. Ya que el destino está abocado a repetirse cíclicamente, debe cumplir su promesa y declarar la guerra contra ella.

“Esta forma es un símbolo de majestuosidad suprema al que se ha conferido poder sobre todo un reino. Es la encarnación unificada de todo lo que conforma a la Shogun Raiden”.
“Hereda el dolor de Ei, el dolor de la inevitable pérdida que conlleva su progreso. Por eso, también hereda la determinación de alcanzar la eternidad”.
“La determinación, el valor, el amor, el odio... Todo ello degenerará y será distorsionado por el implacable paso del tiempo”.
“Solo las reglas podrán permanecer inmutables para toda la eternidad.”', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Shougun_Mitakenarukami.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"EXP de Aventura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_102.png","rareza":3},{"nombre":"EXP de Amistad","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_105.png","rareza":3},{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Prototipo de espada del Norte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101101.png","rareza":4},{"nombre":"Prototipo de arco del Norte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101102.png","rareza":4},{"nombre":"Prototipo de mandoble del Norte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101103.png","rareza":4},{"nombre":"Prototipo de catalizador del Norte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101104.png","rareza":4},{"nombre":"Prototipo de lanza del Norte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_101105.png","rareza":4},{"nombre":"Pedacito de amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104141.png","rareza":2},{"nombre":"Fragmento de amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104142.png","rareza":3},{"nombre":"Trozo de amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104143.png","rareza":4},{"nombre":"Amatista vajrada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_104144.png","rareza":5},{"nombre":"Solvente de sueños","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_113021.png","rareza":4},{"nombre":"Mudra de la Shogun implacable","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_1